"""Ansøgning og CV til Prinfo Denmarks partner i Midtjylland."""
import os
from master_design import MasterDoc
R=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def build():
 m=MasterDoc(os.path.join(R,'Shahram_Ajloo_NNE_DepartmentManagerEI.docx'),lang='da-DK')
 navn='SHAHRAM AJLOO'; titel='Produktionsleder · mennesker, kvalitet og flow'; kontakt='+45 93 99 95 14 · ajlooshahram@gmail.com · linkedin.com/in/shahramajloo · Måløv'
 m.header_banner(navn,titel,kontakt);m.meta('Prinfo Denmark · Produktionsleder hos partnervirksomhed i Midtjylland')
 m.para('**Ansøgning: Fra ordre til levering med styr på mennesker og kapacitet**',after=60)
 for t in [
 'Når en mindre produktion skal levere til både forhandlere og direkte kunder, er den daglige koordinering afgørende: medarbejderne skal kende dagens prioriteringer, kvaliteten skal kontrolleres, og varer skal videre til tiden. Jeg vil samle planlægning, produktion og distribution i et enkelt overblik, der kan bruges af både medarbejdere og ejerleder.',
 'Jeg vil begynde med at følge en ordre gennem virksomheden sammen med medarbejderne og finde de steder, hvor kapacitet, materialer, underleverandører eller kvalitetskontrol kan forsinke leveringen. Derefter vil jeg aftale en realistisk dagsplan, tydelig opgavefordeling og kort opfølgning på afvigelser. Arbejdstider og kompetencer skal planlægges med respekt for både mennesker og ordrebehov.',
 'Jeg leder i dag fem elektrikere og tre lærlinge i ELOHVAC med fuldt resultatansvar. Hos Ventek-Air koordinerede jeg 14 medarbejdere og 11 samtidige projekter; hos ARJ ledede jeg et hold på 12 mekanikere og teknikere med vagt- og materialekoordinering. Erfaringen giver et praktisk grundlag for at lede et mindre team, støtte ejerlederen og holde driften i gang under ferie efter klare aftaler om ansvar og beslutninger.',
 'Jeg har arbejdet med likviditet og cashflow og vil sammen med ejerlederen undersøge, hvor ordreflow, lager, indkøb og betalingstidspunkter påvirker likviditeten, før vi aftaler forbedringer. Det er en foreslået tilgang, ikke en antagelse om virksomhedens aktuelle økonomi. Jeg arbejder struktureret med deadlines og stiller gerne spørgsmål, som hjælper teamet med at finde årsagen til gentagne problemer.',
 'Min baggrund kombinerer mekanisk og elektrisk teknik med drift, vedligehold og kvalitetsarbejde. Jeg vil lære partnerens konkrete grafiske processer og dens arbejdsgange i C5 og Captor; jeg har ikke arbejdet med de to systemer. Prinfo beskriver et samarbejde præget af kompetence, tilgængelighed og ansvarlighed — værdier, jeg vil omsætte til tydelige aftaler og god opfølgning i hverdagen.',
 'Jeg er indstillet på at flytte nær arbejdspladsen i Midtjylland. Jeg vil gerne drøfte produktionsflowet, samarbejdet med ejerlederen og hvilke forbedringer, der vil gøre størst forskel for medarbejdere og kunder.'
 ]:m.para(t,after=44,line=240)
 m.meta('Med venlig hilsen',after=5);m.meta('Shahram Ajloo · +45 93 99 95 14 · ajlooshahram@gmail.com',after=0)
 m.page_break();m.resume_header(navn,titel,kontakt,'OPGAVEN — SIKKER DRIFT FRA PLANLÆGNING TIL DISTRIBUTION')
 m.para('Daglig ledelse af cirka 10 medarbejdere, arbejdstider og produktion; kvalitet, underleverandører, distribution og forbedringer i tæt samarbejde med ejerlederen. Erfaring fra ledelse af mindre teams, teknisk drift og økonomiansvar. Villig til at flytte nær arbejdspladsen i Midtjylland.',after=30)
 m.section('PLANLÆG, FØLG OP, FORBEDR')
 for a,b in [('Planlæg','Skab overblik over ordrer, bemanding, materialer og underleverandører; aftal realistiske deadlines.'),('Følg op','Gør kvalitet, afvigelser og forsendelser synlige, og afklar ansvar ved ferie og fravær.'),('Forbedr','Undersøg årsager til spild og ventetid med medarbejderne; vurder likviditet sammen med ejerlederen.')]:m.bullet(a,b,after=10)
 m.section('ERHVERVSERFARING')
 jobs=[('Ejer / teknisk direktør / elautoriseret maskinmester','ELOHVAC ApS · København · maj 2023–nu','8 medarbejdere inkl. 3 lærlinge · fuldt P&L',[('Ledelse og drift','Leder fem elektrikere og tre lærlinge med daglig planlægning, 1:1 og oplæring; samarbejder med kunder og underleverandører.'),('Planlægning og forbedring','Egne værktøjer til tilbud, tidsplaner og kvalitetstjek bidrog til over 40 % dokumenteret produktivitetsløft.')]),('Projekt- og værkstedsleder','Ventek-Air · jan. 2022–nov. 2022','14 medarbejdere · 11 samtidige projekter',[('Kapacitet og koordinering','Daglig planlægning, fremdrift og koordinering af underentreprenører; tavlemøder og flaskehalsanalyse.')]),('Senior commissioning engineer / projektleder, elsystemer','Novo Nordisk A/S · nov. 2022–jul. 2024','37 samtidige CAPEX-projekter · 25 specialister',[('Kvalitet og samarbejde','Koordinerede engineering, indkøb og anlæg samt økonomi og risiko. FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering.')]),('Drifts- og vedligeholdelsesleder / værkstedstekniker','BIOFOS, Lynetten · aug. 2017–jan. 2022','Kritisk 24/7-drift',[('Teknisk produktion','Forebyggende vedligehold, mekanisk og elektrisk fejlfinding, standardarbejde og PDCA.')]),('Elektromekaniker / produktionsteamleder','ARJ Engineering · dec. 2003–mar. 2010','12 mekanikere og teknikere',[('Arbejdstider og udstyr','Vagtplanlægning, materialekoordinering samt diagnose og reparation af industrielt udstyr.')]),('Medejer og CTO / teknisk ansvarlig, AI-afdeling','Data Power Consultant ApS · 2024–2026 · sideløbende med ELOHVAC','4–10 personer · virksomheden ophørt',[('Systemer og udvikling','Ledede tekniske applikationer fra behov og integration til dokumentation og overdragelse.')])]
 for t,meta,scope,bullets in jobs:
  m.job(t,meta,scope=scope)
  for a,b in bullets:m.bullet(a,b,after=10)
 m.page_break();m.section('UDDANNELSE, METODER OG SPROG')
 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Metoder:** Lean og Six Sigma anvendt i praksis, ikke certificeret; PRINCE2 certificeret. **IT:** Microsoft Office, Excel og SAP ERP; C5 og Captor skal læres. **Sprog:** dansk, engelsk og persisk.',after=20)
 rows=[('Daglig ledelse og kompetencer','ELOHVAC: leder otte medarbejdere inkl. lærlinge, med 1:1 og oplæring. Ventek-Air: 14 medarbejdere; vil afklare kompetencer og ansvar i teamet.'),('Arbejdstider og produktionsplanlægning','ARJ: vagtplanlægning og materialekoordinering for 12 mekanikere og teknikere. Ventek-Air: 11 samtidige projekter med kapacitets- og fremdriftsstyring.'),('Underleverandører og distribution','Ventek-Air: koordinering af underentreprenører. Vil aftale leverancer, ansvar og opfølgning på forsendelser med medarbejdere og leverandører.'),('Kvalitetskontrol','Novo: FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering. Vil lære de grafiske kvalitetskriterier og sikre kontrol i produktionen.'),('Løbende produktionsoptimering','Lean og Six Sigma anvendt i praksis. ELOHVAC: over 40 % produktivitetsløft ved egne planlægnings- og kvalitetsværktøjer; ikke målt hos partneren.'),('Cashflow optimering','Har arbejdet med likviditet og cashflow; konkrete tiltag og resultater er ikke specificeret. ELOHVAC: fuldt P&L. Vil gennemgå drivere med ejerlederen.'),('Daglig drift ved ferie og højre hånd','ELOHVAC: ejerleder med fuldt P&L og otte ansatte. Vil på forhånd afklare beslutningsrum, ansvar og prioriteringer med ejerlederen ved ferie.'),('Produktion og mekanisk teknik','Maskinmester og B.Tech med mekanisk/elektrisk driftserfaring fra BIOFOS og ARJ. Partnerens konkrete grafiske produktion og metoder skal læres.'),('C5, Captor og Microsoft Office','Excel og Microsoft Office samt SAP ERP. C5 og Captor er ikke tidligere anvendt og kræver oplæring; de er en fordel, ikke et krav i opslaget.'),('Selvstændighed, deadlines og kommunikation','ELOHVAC: selvstændig drift og daglig koordinering. Ventek-Air: planlagde 11 samtidige projekter. Dansk anvendes skriftligt og mundtligt.'),('Arbejdssted i Midtjylland','Indstillet på at flytte nær arbejdspladsen. Den præcise adresse er ikke oplyst og skal afklares med Prinfo eller partnervirksomheden.')]
 m.models_table('ROLLEBEHOV — ERFARING OG TILGANG',('Krav i rollen','Erfaring eller foreslået tilgang'),rows,widths=(2600,7746))
 m.section('FØRSTE SKRIDT')
 for x in ['Gennemgå ordreflow, produktionsplan og kvalitetskrav med ejerleder og medarbejdere.','Afklar bemanding, leverancer og beslutningsansvar; følg op på afvigelser og flaskehalse.','Vælg en forbedring sammen med teamet og vurder likviditetens drivere med ledelsen.']:m.bullet('',x,after=10)
 m.save(os.path.join(R,'Shahram_Ajloo_Prinfo_Produktionsleder.docx'))
if __name__=='__main__':build()
